// This file is the minimal host-item portion normally generated by the VSTO
// designer. Keep it small: the add-in currently exposes no ribbon or task pane.
using System;
using Microsoft.Office.Tools;
using Microsoft.Office.Tools.Word;

namespace ThesisAddIn.VSTO;

[Microsoft.VisualStudio.Tools.Applications.Runtime.StartupObject(0)]
[System.Security.Permissions.PermissionSet(System.Security.Permissions.SecurityAction.Demand, Name = "FullTrust")]
public sealed partial class ThisAddIn : AddInBase
{
    internal ThisAddIn(ApplicationFactory factory, IServiceProvider serviceProvider)
        : base(factory, serviceProvider, "AddIn", "ThisAddIn")
    {
        Globals.Factory = factory;
    }

    protected override void Initialize()
    {
        base.Initialize();
        Globals.ThisAddIn = this;
    }

    protected override void FinishInitialization()
    {
        InternalStartup();
        OnStartup();
    }
}

internal static class Globals
{
    private static ThisAddIn? _thisAddIn;
    private static ApplicationFactory? _factory;

    internal static ThisAddIn ThisAddIn
    {
        get => _thisAddIn ?? throw new InvalidOperationException("VSTO 加载项尚未初始化。");
        set => _thisAddIn ??= value;
    }

    internal static ApplicationFactory Factory
    {
        get => _factory ?? throw new InvalidOperationException("VSTO 工厂尚未初始化。");
        set => _factory ??= value;
    }
}
